



SET SQL_MODE="NO_AUTO_VALUE_ON_ZERO";



-- If duplicates: The parameter list (_group, _param and set_) is from the first/top 'selected rows'





CREATE TABLE IF NOT EXISTS `iw_par_dixell_xm670k_groups` (
  `row_date` datetime NOT NULL DEFAULT '2021-01-01 00:00:00',
  `type` varchar(50) NOT NULL DEFAULT '',
  `view_order` mediumint(6) NOT NULL DEFAULT '0',
  `ref` varchar(100) NOT NULL DEFAULT '',
  `value` varchar(200) NOT NULL DEFAULT '',
  UNIQUE KEY `type` (`type`,`view_order`,`ref`,`value`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COMMENT='4.3.4';

-- Fix for existing older table: CREATE TABLE IF NOT EXISTS does not add missing columns
-- This adds view_order before the REPLACE INTO statement runs.
DELIMITER $$
DROP PROCEDURE IF EXISTS `fix_iw_par_dixell_xm670k_groups_view_order` $$
CREATE PROCEDURE `fix_iw_par_dixell_xm670k_groups_view_order`()
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM INFORMATION_SCHEMA.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'iw_par_dixell_xm670k_groups'
      AND COLUMN_NAME = 'view_order'
  ) THEN
    ALTER TABLE `iw_par_dixell_xm670k_groups`
      ADD COLUMN `view_order` mediumint(6) NOT NULL DEFAULT '0' AFTER `type`;
  END IF;
END $$
CALL `fix_iw_par_dixell_xm670k_groups_view_order`() $$
DROP PROCEDURE IF EXISTS `fix_iw_par_dixell_xm670k_groups_view_order` $$
DELIMITER ;







CREATE TABLE IF NOT EXISTS `iw_par_dixell_xm670k_param` (
  `row_date` datetime NOT NULL DEFAULT '2021-01-01 00:00:00',
  `element_id` varchar(100) NOT NULL DEFAULT '',
  `driver_id` varchar(100) NOT NULL DEFAULT '',
  `alias_text` text NOT NULL,
  `menu` varchar(10) NOT NULL DEFAULT '',
  `application` text NOT NULL,
  `parameter_type` text NOT NULL,
  `factory_setting` text NOT NULL,
  `grp` text NOT NULL,
  `att` text NOT NULL,
  `eng_unit` varchar(20) NOT NULL DEFAULT '',
  `format` varchar(20) NOT NULL DEFAULT '',
  `range_min` text NOT NULL,
  `range_max` text NOT NULL,
  `scale` varchar(15) NOT NULL DEFAULT '',
  `raw_min` varchar(15) NOT NULL DEFAULT '',
  `raw_max` varchar(15) NOT NULL DEFAULT '',
  `eng_min` varchar(15) NOT NULL DEFAULT '',
  `eng_max` varchar(15) NOT NULL DEFAULT '',
  `driver_id_extra` varchar(255) NOT NULL DEFAULT '',
  `format_extra` text NOT NULL,
  UNIQUE KEY `element_id` (`element_id`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COMMENT='4.3.4';







CREATE TABLE IF NOT EXISTS `iw_set_dixell_xm670k` (
  `row_date` datetime NOT NULL DEFAULT '2021-01-01 00:00:00',
  `element_id` varchar(100) NOT NULL DEFAULT '',
  `active` enum('0','1') NOT NULL DEFAULT '0',
  `onl_ind` enum('0','1') NOT NULL DEFAULT '1',
  `update_freq` set('','fast','norm','slow','once','never') NOT NULL DEFAULT 'norm',
  `save_data` varchar(20) NOT NULL DEFAULT 'change',
  `save_freq` varchar(20) NOT NULL DEFAULT '',
  `plant_pri` char(1) NOT NULL DEFAULT '',
  `sys_pri` char(1) NOT NULL DEFAULT '',
  `alarm_type` tinyint(3) NOT NULL DEFAULT '0',
  PRIMARY KEY (`element_id`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COMMENT='4.3.4';







